function git(gitArgs) {
  return execFileSync("git", gitArgs, {
    cwd: process.cwd(),
    encoding: "utf8",
    maxBuffer: 128 * 1024 * 1024,
    stdio: ["ignore", "pipe", "pipe"]
  }).trim();
}

function parseArgs(argv) {
  const parsed = {
    list: false,
    json: false,
    reason: "A25 dirty-worktree remediation evidence refresh",
    withDatedDirtyMapReport: false,
    withGeneratedCleanupApply: false
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === "--list") parsed.list = true;
    else if (arg === "--json") parsed.json = true;
    else if (arg === "--with-dated-dirty-map-report") parsed.withDatedDirtyMapReport = true;
    else if (arg === "--with-generated-cleanup-apply") parsed.withGeneratedCleanupApply = true;
    else if (arg === "--reason") parsed.reason = argv[++index] ?? parsed.reason;
    else throw new Error(`Unknown argument: ${arg}`);
  }

  return parsed;
}

function displayCommand(step) {
  const bin = step.bin === process.execPath ? "node" : step.bin;
  return [bin, ...step.args].join(" ");
}

function stepPlan() {
  return activeSteps().map((step, index) => ({
    index: index + 1,
    name: step.name,
    command: displayCommand(step),
    allowFailure: step.allowFailure === true,
    expectedFailures: step.expectedFailures ?? []
  }));
}

function activeSteps() {
  if (!args.withGeneratedCleanupApply) return baseSteps;
  const cleanupStep = {
    name: "A22 owner-approved generated-artifact guarded cleanup apply",
    bin: process.execPath,
    args: ["coordination/release-intake/run-a22-generated-artifact-guarded-cleanup.mjs", "--apply", "--json"]
  };
  const insertAfter = baseSteps.findIndex((step) => step.name === "A22 generated-artifact guarded cleanup current gate");
  if (insertAfter === -1) throw new Error("Could not locate A22 residual authorization gate insertion point");
  return [
    ...baseSteps.slice(0, insertAfter + 1),
    cleanupStep,
    ...baseSteps.slice(insertAfter + 1)
  ];
}

function compact(value, maxLines = 12) {
  const lines = String(value ?? "").trim().split("\n").filter(Boolean);
  if (lines.length <= maxLines) return lines;
  const head = Math.floor(maxLines / 2);
  return [
    ...lines.slice(0, head),
    `... ${lines.length - maxLines} lines omitted ...`,
    ...lines.slice(-(maxLines - head))
  ];
}

function parseJsonOutput(stdout) {
  const text = String(stdout ?? "").trim();
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function sameArray(left, right) {
  return JSON.stringify([...left].sort()) === JSON.stringify([...right].sort());
}

function runStep(step) {
  const result = spawnSync(step.bin, step.args, {
    cwd: root,
    encoding: "utf8",
    maxBuffer: 512 * 1024 * 1024,
    stdio: ["ignore", "pipe", "pipe"]
  });
  const status = typeof result.status === "number" ? result.status : 1;
  const payload = parseJsonOutput(result.stdout);
  const failures = Array.isArray(payload?.failures) ? payload.failures : [];
  const passed = status === 0 || step.allowFailure === true;
  const expectedFailureMismatch = step.expectedFailures
    ? !sameArray(failures, step.expectedFailures)
    : false;

  return {
    name: step.name,
    command: displayCommand(step),
    status,
    passed: passed && !expectedFailureMismatch,
    allowedFailure: step.allowFailure === true && status !== 0,
    expectedFailures: step.expectedFailures ?? [],
    failures,
    stdout: compact(result.stdout),
    stderr: compact(result.stderr, 20),
    error: result.error?.message,
    expectedFailureMismatch
  };
}

function printJson(value) {
  console.log(JSON.stringify(value, null, 2));
}

function printTextSummary(payload) {
  console.log("A25 dirty-worktree remediation evidence refresh");
  console.log(`Root: ${payload.root}`);
  console.log(`Steps: ${payload.summary.passedSteps}/${payload.summary.totalSteps} passed`);
  console.log(`Allowed failures: ${payload.summary.allowedFailures}`);
  console.log(`Result: ${payload.result}`);
  if (payload.failures.length > 0) {
    console.log("Failures:");
    for (const failure of payload.failures) console.log(`- ${failure}`);
  }
}

function main() {
  const plan = stepPlan();
  if (args.list) {
    const payload = {
      generatedAt: new Date().toISOString(),
      root,
      nonDestructiveBoundary: "This runner refreshes A25 evidence only. By default it does not stage, commit, restore, clean, discard, deploy, push, tag, delete branches, remove worktrees, prune worktrees, or run aggregate gates. The optional --with-generated-cleanup-apply mode is limited to owner/A22-approved generated-artifact cleanup.",
      steps: plan
    };
    return args.json ? printJson(payload) : printTextSummary({
      root,
      result: "list",
      summary: { totalSteps: plan.length, passedSteps: 0, allowedFailures: 0 },
      failures: []
    });
  }

  const results = [];
  const steps = activeSteps();
  for (const step of steps) {
    console.log(`RUN ${displayCommand(step)}`);
    const result = runStep(step);
    results.push(result);
    if (result.stdout.length > 0) console.log(result.stdout.join("\n"));
    if (result.stderr.length > 0) console.error(result.stderr.join("\n"));
    if (!result.passed) break;
  }

  const failures = results
    .filter((result) => !result.passed)
    .map((result) => `${result.name} failed`);
  const payload = {
    generatedAt: new Date().toISOString(),
    root,
    result: failures.length === 0 ? "pass" : "fail",
    summary: {
      totalSteps: steps.length,
      executedSteps: results.length,
      passedSteps: results.filter((result) => result.passed).length,
      allowedFailures: results.filter((result) => result.allowedFailure).length
    },
    failures,
    steps: results
  };

  if (args.json) printJson(payload);
  else printTextSummary(payload);

  if (failures.length > 0) process.exit(1);
}

main();
